<?php require '../config/database.php';$pageTitle='Central de chamados';$lista=$pdo->query('SELECT * FROM chamados ORDER BY id')->fetchAll();require '../includes/header.php';?><div class="head"><div><h1>Central de chamados</h1><p class="muted">Investigue, corrija e documente o atendimento.</p></div><span class="badge"><?=count(array_filter($lista,fn($c)=>$c['status']==='Aberto'))?> abertos</span></div><section class="tickets"><?php foreach($lista as $c):?><article class="ticket"><div class="head"><b><?=$c['codigo']?></b><span class="badge"><?=$c['status']?></span></div><h3><?=htmlspecialchars($c['titulo'])?></h3><p class="muted"><?=htmlspecialchars($c['resumo'])?></p><small><?=$c['modulo']?> · Severidade <?=$c['severidade']?></small><p><a class="btn gray" href="visualizar.php?id=<?=$c['id']?>">Analisar chamado →</a></p></article><?php endforeach;?></section><?php require '../includes/footer.php';?>
